from typing import List

def processListOfCommands(commands: List[str]) -> List[str]:
    accounts = {}   # account_id -> [balance, refund_limit 或 None(不限)]
    txs = {}        # txn_id -> {"acct", "amt", "state", "created", "refunded"}

    for cmd in commands:
        tok = cmd.split()
        if tok[0].lstrip("-").isdigit():          # 带时间戳的格式
            ts, op, args = int(tok[0]), tok[1], tok[2:]
        else:
            ts, op, args = None, tok[0], tok[1:]

        if op == "START":
            aid = args[0]
            if aid not in accounts:
                limit = int(args[2]) if len(args) > 2 else None
                accounts[aid] = [int(args[1]), limit]
        elif op == "NEW":
            tid, aid, amt = args[0], args[1], int(args[2])
            if tid not in txs and aid in accounts:
                txs[tid] = {"acct": aid, "amt": amt, "state": "PENDING",
                            "created": ts, "refunded": False}
        else:
            t = txs.get(args[0])
            if t is None:
                continue
            if op == "PROCESS" and t["state"] == "PENDING":
                t["state"] = "IN_PROGRESS"
            elif op == "COMPLETE" and t["state"] in ("PENDING", "IN_PROGRESS"):
                # 样例 3 中 NEW 之后直接 COMPLETE 也生效
                t["state"] = "DONE"
                accounts[t["acct"]][0] += t["amt"]
            elif op == "MODIFY" and t["state"] == "PENDING":
                t["amt"] = int(args[1])
            elif op == "CANCEL" and t["state"] == "IN_PROGRESS":
                t["state"] = "PENDING"
            elif op == "RETURN" and t["state"] == "DONE" and not t["refunded"]:
                limit = accounts[t["acct"]][1]
                if limit is None:
                    ok = True
                elif limit == 0 or ts is None or t["created"] is None:
                    ok = False
                else:
                    ok = ts - t["created"] <= limit   # 从交易创建时刻起算
                if ok:
                    accounts[t["acct"]][0] -= t["amt"]
                    t["refunded"] = True

    return [f"{a} {accounts[a][0]}" for a in sorted(accounts)]
